-- Additive IAM grants: 87ffbff -> efdcb24 (generated by scripts/gen-permission-grants.ts --since rc-rawprod-2026-10-05.1).
-- Idempotent (every insert is NOT EXISTS-guarded); one transaction. Apply with psql -v ON_ERROR_STOP=1
-- against the RawProd MAIN database as the owner (DDL/DML) role. Never instead of this: pnpm db:seed.
-- New permission codes (2): platform:ruh_setting:read, platform:ruh_setting:write
-- New roles (0): none
-- New grants (7):
--   owner                  platform:ruh_setting:read
--   owner                  platform:ruh_setting:write
--   procurement            platform:ruh_setting:read
--   sales                  platform:ruh_setting:read
--   platform_super_admin   platform:ruh_setting:read
--   platform_super_admin   platform:ruh_setting:write
--   showcase               platform:ruh_setting:read

begin;

insert into iam.permission_master (permission_code, permission_name, module_name, status, created_by, updated_by)
select v.code, v.code, split_part(v.code, ':', 1), 'ACTIVE', 'release-grant', 'release-grant'
  from (values ('platform:ruh_setting:read'), ('platform:ruh_setting:write')) as v(code)
 where not exists (select 1 from iam.permission_master p where p.permission_code = v.code);

insert into iam.role_permission_mapping (role_id, permission_id, status, created_by, updated_by)
select r.role_id, p.permission_id, 'ACTIVE', 'release-grant', 'release-grant'
  from (values
    ('owner', 'platform:ruh_setting:read'),
    ('owner', 'platform:ruh_setting:write'),
    ('procurement', 'platform:ruh_setting:read'),
    ('sales', 'platform:ruh_setting:read'),
    ('platform_super_admin', 'platform:ruh_setting:read'),
    ('platform_super_admin', 'platform:ruh_setting:write'),
    ('showcase', 'platform:ruh_setting:read')
  ) as g(role_code, permission_code)
  join iam.role_master r on r.role_code = g.role_code
  join iam.permission_master p on p.permission_code = g.permission_code
 where not exists (select 1 from iam.role_permission_mapping m where m.role_id = r.role_id and m.permission_id = p.permission_id);

commit;
